svg.script:
/*  */
(function() {
  function initEngine() {
    var root = document.querySelector('.a12p3-root');
    if (!root) return;
    var btns = root.querySelectorAll('.a12p3-ancora-btn');

    function setActive(anchor) {
      root.setAttribute('data-active-anchor', anchor);
      btns.forEach(function(btn) {
        var isSelected = btn.getAttribute('data-anchor') === anchor;
        btn.setAttribute('aria-selected', isSelected ? 'true' : 'false');
      });
    }

    btns.forEach(function(btn) {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        var anchor = btn.getAttribute('data-anchor');
        if (anchor) setActive(anchor);
      });

      btn.addEventListener('keydown', function(e) {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          var anchor = btn.getAttribute('data-anchor');
          if (anchor) setActive(anchor);
        }
      });
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initEngine);
  } else {
    initEngine();
  }
})();
/*  */
